from lib import *
S = SS('w68')
steps = [
    step("预期:缓存命中时返回的 TTL 是“剩余寿命”,逐轮减少。实测:每 2 秒向 1.1.1.1 和 8.8.8.8 各问一次 example.net 的 A 记录(权威 TTL 300 秒),8 轮。1.1.1.1 返回的 TTL 依次是 300、110、296、274、101、286、300、298;8.8.8.8 是 300、135、300、133、135、290、123、282。不是一条干净的倒数,而是在 100 多和接近 300 之间来回跳:相邻两轮之差有 190、−186、173、−185 这样的大幅波动,而不是约 2 秒。这说明 1.1.1.1 和 8.8.8.8 这个地址背后是多个独立的缓存节点(任播 / 负载均衡),每次问到的可能是不同节点,各自在不同时刻缓存了这条记录。所以不能从一次查询的 TTL 推断“权威服务器的 TTL”。", t=tl(S(1)), mark=lidx(S(1), '相邻两轮的差'), done=lidx(S(1), '轮次(s)', '        0 ', '        2 ', '        4 '), b=bars([['1.1.1.1 最小 TTL', 101, '101'], ['1.1.1.1 最大 TTL', 300, '300'], ['8.8.8.8 最小 TTL', 123, '123'], ['8.8.8.8 最大 TTL', 300, '300']], 300, mark=[], done=[0, 1, 2, 3]), kv=KV([['权威 TTL', '300 秒'], ['观察到的 TTL', '101~300 乱跳,不是倒数'], ['原因', '地址背后多个缓存节点']], ['原因'])),
    step("到期之后会发生什么:github.com 的权威 TTL 很短(60 秒)。每 5 秒向 8.8.8.8 问一次,17 轮(85 秒),TTL 序列:60、60、60、60、60、55、60、45、60、60、60、55、8、9、39、60、60。最大值就是 60;偏低的值(55、45、8、9、39)说明那一轮问到的缓存节点已经缓存了一段时间,在快过期;下一轮又回到 60,说明过期后重新向权威服务器取,或者换到了另一个节点。8 或 9 秒就是接近到期的节点。往返时间稳定在 180~246 ms。同样,没有一条干净的倒数曲线。", t=tl(S(2)), mark=lidx(S(2), '0s:60'), done=lidx(S(2), 'TTL 往上跳', '每次往返时间'), b=bars([['最大', 60, '60'], ['最低(60 s 轮)', 8, '8']], 60, mark=[1], done=[0]), kv=KV([['权威 TTL', '60 秒'], ['观察到的值', '60 / 55 / 45 / 8 / 9 / 39'], ['往上跳', '5 次(过期重取或换节点)']], ['权威 TTL'])),
    step("缓存命中与未命中差多少:对 8 个随机的不存在子名字(<随机串>.example.net,响应是 NOERROR 加 SOA,TTL 1800)各问两次 1.1.1.1。第一次必须去权威服务器问(未命中):中位 292 ms;紧接着的第二次(应当命中):中位 291 ms;差值中位 1 ms。肉眼看不出命中与否:本机到 1.1.1.1 的往返大约 290 ms,Cloudflare 在自家网络里再向权威服务器取一次的耗时,淹没在这 290 ms 里了(这是推断,我没有测 1.1.1.1 的内部耗时)。缓存的好处在这个测试里体现不出来,在本机之外的网络上才看得到(下一节看本机操作系统的缓存,那里差别很大)。", t=tl(S(3)), mark=lidx(S(3), '第一次(未命中)', '第二次(命中)'), done=lidx(S(3), '这些随机名字的响应'), b=bars([['第一次(未命中)', 292, '292 ms'], ['第二次(命中)', 291, '291 ms']], 300, mark=[], done=[0, 1]), kv=KV([['未命中', '中位 292 ms'], ['命中', '中位 291 ms'], ['差值', '1 ms,被网络往返淹没']], ['差值'])),
    step("负缓存(RFC 2308):不存在的名字也会被缓存,时间 = min(响应里 SOA 记录的 TTL, SOA 的 minimum 字段)。随机的 .invalid 名字 → RCODE NXDOMAIN,授权区 SOA 的 TTL = 86400 秒,minimum = 86400 秒,负缓存时间 = 86400 秒(一整天)。每 3 秒再问同一个名字,SOA 的 TTL 是 86398、86400、86389、86400——同样因为多个节点,不是单调递减。另外的对照:example.net 的 SRV 记录 → RCODE NOERROR、回答 0 条、授权区有 SOA(TTL 1800,minimum 1800);隔 2 秒再问 3 次,TTL 都是 1800,没有看到倒数。“名字存在但没有这种类型”(NODATA)也会带 SOA,同样可以被负缓存。", t=tl(S(4)), mark=lidx(S(4), '.invalid → RCODE NXDOMAIN', '对照 NODATA'), done=lidx(S(4), '之后每 3 秒再问'), b=bars([['NXDOMAIN 的 SOA TTL', 86400, '86400 秒'], ['NODATA 的 SOA TTL', 1800, '1800 秒']], 86400, mark=[0], done=[1]), kv=KV([['NXDOMAIN(.invalid)', '负缓存 86400 秒'], ['NODATA(example.net SRV)', 'SOA TTL 1800 秒'], ['倒数', '多节点,没有看到干净的倒数']], ['NXDOMAIN(.invalid)'])),
    step("本机操作系统有自己的缓存。用 getaddrinfo 对同一个名字连续调用:example.net 第一次 80.9 ms,之后 0.7、0.3、0.3、0.3、0.3 ms;一个随机的不存在子名字第一次 2017.2 ms(2 秒——原因我没有查,像是一次超时重试),之后 1.0、0.4、0.3 ms;随机的 .invalid 名字第一次 127.8 ms,之后 0.7、0.3、0.3 ms。正向答案和否定答案都被缓存,命中时耗时降到 0.3~1 ms。这里差别巨大(上百倍到两千倍),因为命中完全不用离开本机。Python 自己没有缓存,看到的是 macOS 的 mDNSResponder 缓存。", t=tl(S(5)), mark=lidx(S(5), '随机的不存在子名字', 'example.net(存在)'), done=lidx(S(5), '随机的 .invalid 名字'), b=bars([['example.net 第 1 次', 80.9, '80.9 ms'], ['example.net 第 2 次', 0.7, '0.7 ms'], ['不存在子名字 第 1 次', 2017.2, '2017.2 ms'], ['不存在子名字 第 2 次', 1.0, '1.0 ms']], 2017.2, mark=[2], done=[0, 1, 3]), kv=KV([['首次解析', '80.9~2017.2 ms'], ['缓存命中', '0.3~1.0 ms'], ['正向与否定答案', '都被缓存']], ['缓存命中'])),
]
A = mkartw('w68', 68, '网络协议,DNS,缓存,TTL,负缓存,NXDOMAIN,SOA,mDNSResponder,真实验证,动画演示',
    '实测 DNS 缓存:1.1.1.1 / 8.8.8.8 返回的 TTL 在 101~300 间乱跳(背后多个缓存节点,没有干净的倒数);.invalid 的 NXDOMAIN 负缓存 86400 秒,NODATA 的 SOA TTL 1800 秒;对公网解析器命中与否在 290 ms 往返里看不出(差 1 ms),但本机操作系统缓存把 getaddrinfo 从 80.9 ms 降到 0.3 ms。',
    'DNS 的快慢,一半靠缓存,一半靠 TTL 管着缓存什么时候失效。这篇在本机上看缓存的痕迹:公网解析器给出的 TTL 到底怎么变,负缓存(不存在的名字也会缓存)的时间由谁决定,命中缓存省下多少时间,本机操作系统自己又缓存了什么。有一半的实验结果和教科书上的整齐倒数不一样,我如实写。',
    [('101 ~ 300', '权威 TTL 300 秒时,1.1.1.1 实测返回的 TTL 范围(不是整齐的倒数)'), ('86400 秒', '.invalid 的 NXDOMAIN 响应里 SOA 给出的负缓存时间'), ('80.9 → 0.3 ms', '本机 getaddrinfo 解析 example.net 第一次与之后几次的耗时')],
    [('TTL 的倒数', '<p>缓存命中返回的是剩余寿命,理论上逐渐减小。但公网解析器地址背后有很多缓存节点,每次问到的节点不同,TTL 来回跳。</p>'),
     ('过期与重取', '<p>60 秒 TTL 的 github.com,8.8.8.8 返回 60 / 55 / 45 / 8 / 9 / 39 …,没有清晰的倒数曲线。</p>'),
     ('命中与未命中', '<p>对 1.1.1.1 命中与否只差 1 ms,被 290 ms 的网络往返淹没。</p>'),
     ('负缓存', '<p>不存在的名字(NXDOMAIN)和名字存在但没有这种记录(NODATA)都带 SOA,缓存时间取 SOA TTL 与 minimum 的较小者。</p>'),
     ('本机缓存', '<p>操作系统缓存正向和否定答案,命中时 0.3~1 ms。</p>')],
    steps,
    [ENV_W + '。向 1.1.1.1 和 8.8.8.8 发了几百个普通 DNS 查询;这两个地址背后是多个缓存节点,TTL 观察值每次运行不同;第三节的“命中”只是第二次查询,不保证落在同一个节点',
     '没有验证:单个缓存节点内部的 TTL 倒数(需要能固定到同一个节点);解析器对 TTL 的上下限钳制(很多解析器会把过短或过长的 TTL 改掉);EDNS 客户端子网(ECS)对缓存的影响;预取(prefetch)和过期服务(serve-stale)的行为;getaddrinfo 第一次调用 2017.2 ms 的原因;本机缓存的 TTL 是否与 DNS 响应的 TTL 一致'],
    '缓存与 TTL')
